import sympy
import sympy.ntheory
from sympy import Poly
from sympy.abc import x, y, z

CONDITION_LABELS = [
    "H_1: R is a principal ideal domain",
    "¬Q: I is not generated by p^n for any prime p and n > 0"
]

N_HYP = 1
NEG_Q_INDEX = 1

def conditions(witness) -> list[bool]:
    try:
        # The witness is expected to be the generator of an ideal I in a PID R.
        # We support integers (representing ideals in Z) and polynomials (ideals in Q[x]).
        if isinstance(witness, tuple) and len(witness) == 2:
            ring, ideal_gen = witness
            witness = ideal_gen
            
        if isinstance(witness, (int, sympy.Integer)):
            a = abs(int(witness))
            h1 = True  # Z is a PID
            
            if a == 0 or a == 1:
                is_prime_power = False
            else:
                factors = sympy.ntheory.factorint(a)
                is_prime_power = (len(factors) == 1)
                
            neg_q = not is_prime_power
            return [h1, neg_q]
            
        elif isinstance(witness, sympy.Expr) or isinstance(witness, sympy.Poly):
            poly = sympy.Poly(witness)
            h1 = True  # Q[x] is a PID
            
            factors = poly.factor_list()[1]
            is_prime_power = (len(factors) == 1)
            
            neg_q = not is_prime_power
            return [h1, neg_q]
            
    except Exception:
        pass
        
    return [False, False]